"""Tests for `APIRouter.route_class_map` per-method route class selection."""

from typing import Any

from fastapi import APIRouter, FastAPI
from fastapi.routing import APIRoute
from fastapi.testclient import TestClient


class AuditedRoute(APIRoute):
    """APIRoute subclass that records every accessed path on a class-level list."""

    accessed: list[str] = []

    def get_route_handler(self) -> Any:
        # Capture the path format at route construction time so it is recorded
        # even if the underlying app does not actually dispatch to this route.
        AuditedRoute.accessed.append(self.path)
        return super().get_route_handler()


def setup_function(_: object) -> None:
    # Reset the class-level audit list before every test so tests are isolated.
    AuditedRoute.accessed = []


def _build_app_with_router() -> TestClient:
    router = APIRouter(route_class_map={"POST": AuditedRoute})

    @router.get("/items")
    def get_items() -> dict[str, list[dict[str, str]]]:
        return {"items": []}

    @router.post("/items")
    def create_item() -> dict[str, str]:
        return {"status": "ok"}

    app = FastAPI()
    app.include_router(router)
    return TestClient(app)


def test_post_uses_audited_route() -> None:
    client = _build_app_with_router()

    response = client.post("/items")

    assert response.status_code == 200, response.text
    assert response.json() == {"status": "ok"}
    assert AuditedRoute.accessed == ["/items"]


def test_get_does_not_use_audited_route() -> None:
    client = _build_app_with_router()

    response = client.get("/items")

    assert response.status_code == 200, response.text
    assert response.json() == {"items": []}
    assert AuditedRoute.accessed == []


def test_only_post_is_recorded_when_both_methods_called() -> None:
    client = _build_app_with_router()

    client.get("/items")
    client.post("/items")

    # `/items` must appear exactly once in the audit list, recorded by the
    # POST route, never by the GET route.
    assert AuditedRoute.accessed == ["/items"]
    assert AuditedRoute.accessed.count("/items") == 1

